pv=[268,281,322,309,334,312,293];prev=[231,240,236,255,262,270,215]
def chart(w=1150,h=240,vals=pv,pvals=prev,labels=D,tip=True):
  mx=max(400,max(vals)+40);L=36;B=24;T=8;W=w-L-8;H=h-B-T
  X=lambda i:L+W*i/(len(vals)-1);Y=lambda v:T+H*(1-v/mx)
  g=''.join(f'<line class="grid" x1="{L}" x2="{w-8}" y1="{Y(v):.1f}" y2="{Y(v):.1f}"/><text class="ax" x="{L-8}" y="{Y(v)+4:.1f}" text-anchor="end">{v}</text>' for v in (0,100,200,300,400))
  ax=''.join(f'<text class="ax" x="{X(i):.1f}" y="{h-6}" text-anchor="{'start' if i==0 else 'end' if i==len(labels)-1 else 'middle'}">{l}</text>' for i,l in enumerate(labels))
  def path(vs):
    p=[(X(i),Y(v)) for i,v in enumerate(vs)];s=f'M{p[0][0]:.1f},{p[0][1]:.1f}'
    for a,b in zip(p,p[1:]):
      cx=(a[0]+b[0])/2;s+=f' C{cx:.1f},{a[1]:.1f} {cx:.1f},{b[1]:.1f} {b[0]:.1f},{b[1]:.1f}'
    return s
  ln=path(vals);ar=ln+f' L{X(len(vals)-1):.1f},{Y(0):.1f} L{L},{Y(0):.1f} Z'
  t=''
  if tip:
    i=4;t=f'<line x1="{X(i):.1f}" x2="{X(i):.1f}" y1="{T}" y2="{Y(0):.1f}" stroke="var(--border-strong)" class="fade"/><circle cx="{X(i):.1f}" cy="{Y(vals[i]):.1f}" r="4" fill="var(--surface)" stroke="var(--chart-1)" stroke-width="2" class="fade"/>'
  svg=f'<svg width="100%" viewBox="0 0 {w} {h}" preserveAspectRatio="none" style="display:block;height:{h}px"><defs><linearGradient id="g" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--chart-1)" stop-opacity=".16"/><stop offset="1" stop-color="var(--chart-1)" stop-opacity="0"/></linearGradient></defs>{g}{ax}<path class="pv fade" d="{path(pvals)}"/><path class="ar fade" d="{ar}"/><path class="ln draw" d="{ln}"/>{t}</svg>'
  if tip:
    svg=f'<div style="position:relative">{svg}<div class="tip fade" style="left:{X(4)/w*100+1.5:.1f}%;top:18px"><div class="sub" style="margin-bottom:4px">10月24日 周六</div><div class="r"><span><i style="display:inline-block;width:8px;height:8px;border-radius:2px;background:var(--chart-1);margin-right:6px"></i>浏览量</span><b class="num">334</b></div><div class="r" style="color:var(--fg-3)"><span>上一期</span><span class="num">262</span></div></div></div>'
  return svg
def hdr(active='总览',mobile=False):
  tabs=['总览','实时','页面','来源','受众','事件','漏斗','SEO','AI 助手','设置']
