  right='' if mobile else '<span class="live"><span class="dot"></span><b class="num" style="color:var(--fg)" data-tick="23">23</b> 人在线</span><button class="btn ghost" style="color:var(--fg-2)">文档</button><button class="ibtn" title="切换主题">◐</button><span class="avatar"></span>'
  more='' if mobile else '<a class="tab" style="color:var(--fg-3)">更多 ▾</a>'
  return f'''<header class="hdr"><div class="in"><span class="logo"><span class="mark">泽</span>{"" if mobile else "白泽"}</span><span class="slash">/</span><span class="site"><span class="fav"></span>示例博客 <span class="chev">⌄</span></span>{"" if mobile else '<span class="sub">blog.example.com</span>'}<span class="sp"></span>{right}{'<span class="live"><span class="dot"></span><b class="num" style="color:var(--fg)">23</b></span>' if mobile else ''}</div></header><nav class="tabs"><div class="in">{t}{more}</div></nav>'''
