def lst(title,tabs,rows,col='访客',col2=None,icon=None):
  mx=max(r[1] for r in rows)
  tb=''.join(f'<span class="{"on" if i==0 else ""}">{t}</span>' for i,t in enumerate(tabs))
  rr=''.join(f'<div class="row"><span class="bar-bg" style="width:{r[1]/mx*100*.92:.1f}%;animation-delay:{i*40}ms"></span>{f"<span class=ico>{r[3]}</span>" if len(r)>3 else ""}<span class="k">{r[0]}</span><span class="m num">{r[1]:,}</span>{f"<span class=m2>{r[2]}</span>" if col2 else ""}</div>' for i,r in enumerate(rows))
  return f'<section class="card"><div class="card-h"><span class="ttl">{title}</span><div class="mini-tabs">{tb}</div><span class="sp"></span><button class="ibtn" style="width:24px;height:24px" title="展开">⤢</button></div><div class="list"><div class="lh"><span>{tabs[0] if tabs else ""}</span><span style="display:flex;gap:8px"><span style="width:64px;text-align:right">{col}</span>{f"<span style=width:56px;text-align:right>{col2}</span>" if col2 else ""}</span></div>{rr}</div><a class="more">查看全部 →</a></section>'
